def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 1:
        return 0

    # Initialize increasing and decreasing arrays
    increasing = [1] * n
    decreasing = [1] * n

    # Fill increasing array
    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            increasing[i] = increasing[i - 1] + 1

    # Fill decreasing array
    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            decreasing[i] = decreasing[i + 1] + 1

    # Calculate the minimum number of students to leave
    min_leave = n
    for i in range(n):
        total_students = increasing[i] + decreasing[i] - 1
        min_leave = min(min_leave, n - total_students)

    return min_leave

