def min_groups(w, n, prices):
    if w <= 0:
        raise ValueError("The maximum allowed sum of prices for any group (w) must be greater than 0.")
    if n <= 0:
        raise ValueError("The total number of souvenirs (n) must be greater than 0.")
    if len(prices) != n:
        raise ValueError("The length of prices list must be equal to the number of souvenirs (n).")
    if any(price > w for price in prices):
        raise ValueError("No souvenir price can exceed the maximum allowed sum for any group (w).")

    # Sort prices to try and pair the most expensive with the least expensive
    prices.sort()
    left, right = 0, n - 1
    groups = 0

    while left <= right:
        if prices[left] + prices[right] <= w:
            left += 1
        right -= 1
        groups += 1

    return groups

